const payloadData = typeof payload !== "undefined" ? payload : undefined;
const body = responseData ?? payloadData;
const input = Array.isArray(body) ? body : (body?.values ?? body?.permissionSchemes ?? []);
if (!Array.isArray(input)) return [];
const rows = input;
return rows.map((row) => {
  const item = row ?? {};
  return {
    ...item,
    id: item.id !== undefined && item.id !== null ? String(item.id) : item.id
  };
});

